const state={user:null,permissions:new Set(),view:'Dashboard',data:null,error:'',message:'',loading:false,cache:{},productQuery:'',supplierQuery:'',customerQuery:'',posCart:[],posProducts:[],posPayments:[]};
const $=s=>document.querySelector(s);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>Number(x||0).toLocaleString('en-UG',{maximumFractionDigits:2})+' UGX';
const num=x=>Number(x||0).toLocaleString('en-UG',{maximumFractionDigits:3});
function cookie(name){return document.cookie.split(';').map(x=>x.trim()).find(x=>x.startsWith(name+'='))?.slice(name.length+1)||''}
async function api(path,opt={}){const headers={'Content-Type':'application/json',...(opt.headers||{})};const csrf=cookie('amaal_csrf');if(csrf)headers['X-CSRF-Token']=csrf;const r=await fetch('/api'+path,{...opt,headers,credentials:'same-origin'});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||`Request failed (${r.status})`);return d}
function has(p){return state.permissions.has(p)}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label>${esc(label)}</label><input name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function area(label,name,value='',extra=''){return `<div class="field span2"><label>${esc(label)}</label><textarea name="${esc(name)}" ${extra}>${esc(value)}</textarea></div>`}
function select(label,name,value,opts){return `<div class="field"><label>${esc(label)}</label><select name="${esc(name)}">${opts.map(o=>`<option value="${esc(o[0])}" ${String(value)===String(o[0])?'selected':''}>${esc(o[1])}</option>`).join('')}</select></div>`}
function btn(text,action,cls='btn'){return `<button type="button" class="${cls}" data-action="${esc(action)}">${esc(text)}</button>`}
function pill(v){const x=String(v??'');const c=/active|published|completed|received|in stock|success/i.test(x)?'ok':/inactive|hidden|cancelled|suspended|failed|damage|loss/i.test(x)?'bad':/draft|submitted|open|pending|in progress|approved|shipped/i.test(x)?'warn':'';return `<span class="pill ${c}">${esc(x||'—')}</span>`}
function table(headers,rows,emptyTitle='Nothing to display yet.',emptyText='Create your first record to get started.'){return `<div class="tablewrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}"><div class="empty"><strong>${esc(emptyTitle)}</strong>${esc(emptyText)}</div></td></tr>`}</tbody></table></div>`}
function modal(title,html){const wrap=document.createElement('div');wrap.className='modal';wrap.innerHTML=`<div class="modalbox"><div class="modalhead"><h2>${esc(title)}</h2><button class="close" type="button">×</button></div><div class="modalbody">${html}</div></div>`;document.body.appendChild(wrap);wrap.querySelector('.close').onclick=()=>wrap.remove();wrap.onclick=e=>{if(e.target===wrap)wrap.remove()};return wrap.querySelector('.modalbody')}
function formModal(title,fields,submit,label='Save'){const body=modal(title,`<form id="dynamicForm"><div class="formgrid">${fields.join('')}</div><div id="formMsg"></div><div class="toolbar" style="justify-content:flex-end"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary">${esc(label)}</button></div></form>`);const form=body.querySelector('#dynamicForm');body.querySelector('[data-close]').onclick=()=>body.closest('.modal').remove();form.onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(form).entries());try{const r=await submit(f);body.closest('.modal').remove();state.cache={};state.message='Saved successfully';await load(state.view);return r}catch(err){body.querySelector('#formMsg').innerHTML=`<div class="error">${esc(err.message)}</div>`}};return body}
async function boot(){try{const h=await api('/health');if(!h.ok)throw Error('Administration service is not ready.');try{const m=await api('/me');state.user=m.user;state.permissions=new Set(m.permissions);render();await load('Dashboard');return}catch{}const s=await api('/setup/status');renderAuth(!!s.configured)}catch(e){$('#app').innerHTML=`<div class="auth" style="min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px;background:#0f172a"><div class="authbox" style="width:min(460px,100%);background:#fff;border-radius:20px;padding:28px"><h1>Amaal Telecoms</h1><p class="muted">The administration service could not be reached.</p><div class="error">${esc(e.message)}</div></div></div>`}}
function renderAuth(configured){$('#app').innerHTML=`<div style="min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px;background:#0f172a"><form id="authform" style="width:min(460px,100%);background:#fff;border-radius:20px;padding:28px;box-shadow:0 25px 70px #0005"><h1 style="margin:0">Amaal Telecoms</h1><p class="muted">${configured?'Secure administrator sign in.':'Set up the first administrator account.'}</p>${!configured?field('Company name','companyName','Amaal Telecoms'):''}${field('Administrator email','email','','email','required')}${field('Password','password','','password','required minlength="12"')}${!configured?field('Phone','phone'):''}${!configured?field('Address','address'):''}${configured?field('Authenticator code (if enabled)','code','','text','inputmode="numeric" autocomplete="one-time-code"'):''}<div id="authmsg"></div><button class="btn primary" style="width:100%;margin-top:8px">${configured?'Sign in':'Create administrator'}</button></form></div>`;$('#authform').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target).entries());try{const d=await api(configured?'/login':'/setup',{method:'POST',body:JSON.stringify(body)});state.user=d.user;const m=await api('/me');state.permissions=new Set(m.permissions);render();await load('Dashboard')}catch(x){$('#authmsg').innerHTML=`<div class="error">${esc(x.message)}</div>`}}}
const navGroups=[['Overview',['Dashboard']],['Catalog',['Products','Categories','Brands','Tags']],['Inventory',['Inventory','Stock','Locations','Stock Receipts','Adjustments','Transfers','Reservations','Serialized Units','Stock Movements','Stocktakes','Damage & Loss']],['Administration',['Staff','Roles','Invitations','Sessions']],['Organization',['Organization','Departments']],['Governance',['Audit','Notifications','Settings','Feature Flags']],['Security',['Security']],['Procurement',['Procurement','Suppliers','Requisitions','Purchase Orders','Goods Receipts','Supplier Invoices','Supplier Payments']],['Customers & CRM',['Customers','Customer Cases','CRM Tasks','Customer Tags']],['Sales & POS',['Sales']]];
const routeMap={Dashboard:'/dashboard',Inventory:'/inventory/summary',Stock:'/inventory/stock?limit=100&offset=0',Locations:'/inventory/locations','Stock Receipts':'/inventory/receipts',Adjustments:'/inventory/adjustments',Transfers:'/inventory/transfers',Reservations:'/inventory/reservations','Serialized Units':'/inventory/serialized','Stock Movements':'/inventory/movements',Stocktakes:'/inventory/stocktakes','Damage & Loss':'/inventory/incidents',Products:'/catalog/products?limit=50&offset=0',Categories:'/catalog/categories',Brands:'/catalog/brands',Tags:'/catalog/tags',Staff:'/staff',Roles:'/roles',Invitations:'/invitations',Sessions:'/sessions/all',Organization:'/organization',Departments:'/departments',Audit:'/audit',Notifications:'/notifications',Settings:'/settings','Feature Flags':'/feature-flags',Security:'/security/policy',Procurement:'/procurement/summary',Suppliers:'/suppliers',Requisitions:'/procurement/requisitions','Purchase Orders':'/procurement/orders','Goods Receipts':'/procurement/receipts','Supplier Invoices':'/procurement/invoices','Supplier Payments':'/procurement/payments',Customers:'/customers?limit=100&offset=0','Customer Cases':'/support/cases','CRM Tasks':'/crm/tasks','Customer Tags':'/customer-tags',Sales:'/sales'};
function render(){const nav=navGroups.map(([g,items])=>`<div class="section">${g}</div>`+items.map(v=>`<button class="nav ${state.view===v?'active':''}" data-nav="${v}">${v}</button>`).join('')).join('');$('#app').innerHTML=`<div class="layout"><aside class="side"><div class="brand">Amaal Telecoms<small>Administration</small></div>${nav}<div class="userbox"><b style="color:#e2e8f0">${esc(state.user?.name||'Administrator')}</b><br>${esc(state.user?.email||'')}<br>${btn('Sign out','logout','nav')}</div></aside><main class="main"><div class="mobilebar"><b>Amaal Telecoms</b>${btn('Sign out','logout')}</div><div class="top"><div><h1 class="title">${esc(state.view)}</h1><p class="sub">Business operations, security and administration</p></div><div>${state.loading?'Loading…':''}</div></div><div id="flash"></div><div id="content" class="spinner">Loading…</div></main></div>`;document.querySelectorAll('[data-nav]').forEach(x=>x.onclick=async()=>{state.view=x.dataset.nav;render();await load(state.view)});document.querySelectorAll('[data-action="logout"]').forEach(x=>x.onclick=logout)}
function flash(){const f=$('#flash');if(!f)return;f.innerHTML=state.error?`<div class="error">${esc(state.error)}</div>`:state.message?`<div class="success">${esc(state.message)}</div>`:'';state.error='';state.message=''}
async function ensureData(kind){if(state.cache[kind])return state.cache[kind];const url={products:'/catalog/products?limit=100&offset=0',variants:'/catalog/products?limit=100&offset=0',locations:'/inventory/locations',categories:'/catalog/categories',brands:'/catalog/brands',roles:'/roles',departments:'/departments'}[kind];if(!url)return[];const d=await api(url);state.cache[kind]=d;return d}
async function load(v){state.loading=true;try{let path=routeMap[v];if(v==='Products')path=`/catalog/products?limit=50&offset=0&q=${encodeURIComponent(state.productQuery)}`;if(v==='Suppliers')path=`/suppliers?limit=100&q=${encodeURIComponent(state.supplierQuery)}`;if(v==='Customers')path=`/customers?limit=100&offset=0&q=${encodeURIComponent(state.customerQuery)}`;if(v==='Sales'){state.data={summary:await api('/sales/summary'),sales:await api('/sales?limit=200')};renderView();return}if(v==='Customer')path=`/customers/${state.data?.id}`;state.data=await api(path);if(v==='Products')state.data.summary=await api('/catalog/summary');renderView()}catch(e){state.error=e.message;renderView()}finally{state.loading=false;flash()}}

function customers(rows){rows=rows||[];return `<div class="hero"><div class="kicker">Customers & CRM</div><h2 style="margin:6px 0">Customer 360</h2><p class="muted">Manage individual, business and corporate customers, relationships, support and privacy from one place.</p></div><div class="toolbar">${has('customers.manage')?btn('Add customer','add-customer','btn primary'):''}${has('customers.export')?btn('Export customers','export-customers'):''}<div class="search"><input id="customerSearch" value="${esc(state.customerQuery||'')}" placeholder="Search name, phone, email or customer number"><button class="btn" data-action="search-customers">Search</button></div></div>${table(['Customer','Type','Contact','Location','Outstanding','Cases','Status','Actions'],rows.map(r=>`<tr><td><b>${esc(r.name)}</b><br><span class="muted">${esc(r.customer_no)}</span>${r.company_name?`<br><span class="muted">${esc(r.company_name)}</span>`:''}</td><td>${esc(r.customer_type)}</td><td>${esc(r.phone)}${r.email?`<br><span class="muted">${esc(r.email)}</span>`:''}</td><td>${esc([r.city,r.region,r.country_code].filter(Boolean).join(', '))}</td><td>${money(r.outstanding_balance)}</td><td>${num(r.open_cases)}</td><td>${pill(r.status)}</td><td class="actions">${btn('Open','customer:'+r.id)}${has('customers.manage')?btn('Edit','edit-customer:'+r.id):''}</td></tr>`),'No customers yet','Add your first customer to begin customer management.')}`}
function customerCases(rows){return `<div class="hero"><div class="kicker">Customer Service</div><h2 style="margin:6px 0">Support cases</h2><p class="muted">Track complaints, requests, escalations and resolutions with a complete customer audit trail.</p></div>${table(['Case','Customer','Priority','Channel','Status','Assignee','Created','Actions'],(rows||[]).map(r=>`<tr><td><b>${esc(r.case_no)}</b><br>${esc(r.title)}</td><td>${esc(r.customer_name)}<br><span class="muted">${esc(r.customer_no)}</span></td><td>${pill(r.priority)}</td><td>${esc(r.channel)}</td><td>${pill(r.status)}</td><td>${esc(r.assignee_email||'Unassigned')}</td><td>${new Date(r.created_at).toLocaleString()}</td><td class="actions">${has('support.manage')?btn('Update','update-case:'+r.id):''}</td></tr>`),'No support cases','Cases created for customers will appear here.')}</div>`}
function crmTasks(rows){return `<div class="hero"><div class="kicker">CRM</div><h2 style="margin:6px 0">Follow-ups</h2><p class="muted">Upcoming customer follow-ups recorded by staff.</p></div>${table(['Customer','Interaction','Channel','Follow-up','Assigned','Outcome'],(rows||[]).map(r=>`<tr><td><b>${esc(r.customer_name)}</b><br><span class="muted">${esc(r.customer_no)}</span></td><td>${esc(r.type)}<br>${esc(r.summary)}</td><td>${esc(r.channel||'—')}</td><td>${esc(r.next_follow_up||'—')}</td><td>${esc(r.assigned_to||'—')}</td><td>${esc(r.outcome||'Pending')}</td></tr>`),'No upcoming follow-ups','Record a CRM interaction with a follow-up date.')}</div>`}
function customerTags(rows){return `<div class="hero"><div class="kicker">Customer Segmentation</div><h2 style="margin:6px 0">Customer tags</h2><p class="muted">Create reusable segments such as VIP, corporate, returning or inactive customers.</p></div><div class="toolbar">${has('crm.manage')?btn('Add tag','add-customer-tag','btn primary'):''}</div>${table(['Tag','Description','Created'],(rows||[]).map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${esc(r.description)}</td><td>${new Date(r.created_at).toLocaleString()}</td></tr>`),'No customer tags','Create your first segment.')}</div>`}
function customerDetail(d){return `<div class="hero"><div class="kicker">Customer ${esc(d.customer_no)}</div><h2 style="margin:6px 0">${esc(d.name)}</h2><p class="muted">${esc(d.customer_type)} ${d.company_name?'· '+esc(d.company_name):''}</p><div class="actions">${has('customers.manage')?btn('Edit customer','edit-customer:'+d.id,'btn primary'):''}${has('crm.manage')?btn('Log interaction','add-interaction:'+d.id):''}${has('support.manage')?btn('Create support case','add-case:'+d.id):''}${has('customers.privacy')?btn('Privacy & consent','privacy:'+d.id):''}</div></div><div class="grid"><div class="card"><div class="label">Phone</div><div class="metric" style="font-size:20px">${esc(d.phone)}</div><div class="muted">${esc(d.email||'No email')}</div></div><div class="card"><div class="label">Outstanding balance</div><div class="metric" style="font-size:20px">${money(d.outstanding_balance)}</div><div class="muted">Credit limit ${money(d.credit_limit)}</div></div><div class="card"><div class="label">Open cases</div><div class="metric">${num((d.cases||[]).filter(x=>!['Resolved','Closed'].includes(x.status)).length)}</div></div></div><div class="grid2"><div class="card"><h3 class="sectiontitle">Profile</h3><div class="statline"><span>Address</span><b>${esc([d.address_line1,d.address_line2,d.city,d.region,d.country_code].filter(Boolean).join(', ')||'—')}</b></div><div class="statline"><span>Tax number</span><b>${esc(d.tax_number||'—')}</b></div><div class="statline"><span>Status</span><b>${pill(d.status)}</b></div><div class="statline"><span>Tags</span><b>${(d.tags||[]).map(x=>esc(x.name)).join(', ')||'—'}</b></div></div><div class="card"><h3 class="sectiontitle">Recent interactions</h3>${table(['Type','Summary','Channel','Follow-up'],(d.interactions||[]).slice(0,12).map(x=>`<tr><td>${esc(x.type)}</td><td>${esc(x.summary)}</td><td>${esc(x.channel||'—')}</td><td>${esc(x.next_follow_up||'—')}</td></tr>`),'No interactions','Customer interactions will appear here.')}</div></div><div class="grid2"><div class="card"><h3 class="sectiontitle">Addresses</h3>${table(['Label','Address','Default'],(d.addresses||[]).map(x=>`<tr><td>${esc(x.label)}</td><td>${esc([x.address_line1,x.address_line2,x.city,x.region,x.country_code].filter(Boolean).join(', '))}</td><td>${x.is_default?'Yes':'No'}</td></tr>`),'No addresses','Add a customer address.')}${has('customers.manage')?btn('Add address','add-address:'+d.id):''}</div><div class="card"><h3 class="sectiontitle">Support cases</h3>${table(['Case','Priority','Status','Created'],(d.cases||[]).map(x=>`<tr><td>${esc(x.case_no)}<br>${esc(x.title)}</td><td>${pill(x.priority)}</td><td>${pill(x.status)}</td><td>${new Date(x.created_at).toLocaleDateString()}</td></tr>`),'No support cases','No cases have been opened for this customer.')}</div></div>`}
function renderView(){const c=$('#content');if(!c)return;const d=state.data;const views={Dashboard:dashboard,Inventory:inventory,Stock:stockView,Locations:locations, 'Stock Receipts':receipts,Adjustments:adjustments,Transfers:transfers,Reservations:reservations,'Serialized Units':serialized,'Stock Movements':movements,Stocktakes:stocktakes, 'Damage & Loss':incidents,Products:products,Categories:categories,Brands:brands,Tags:tags,Staff:staff,Roles:roles,Invitations:invitations,Sessions:sessions,Organization:organization,Departments:departments,Audit:audit,Notifications:notifications,Settings:settings, 'Feature Flags':featureFlags,Security:security,Procurement:procurement,Suppliers:suppliers,Customers:customers,'Customer Cases':customerCases,'CRM Tasks':crmTasks,'Customer Tags':customerTags,Sales:salesView,Requisitions:requisitions,'Purchase Orders':purchaseOrders,'Goods Receipts':goodsReceipts,'Supplier Invoices':supplierInvoices,'Supplier Payments':supplierPayments};if(state.view==='Customer'){c.innerHTML=customerDetail(d);bindView();flash();return} const fn=views[state.view];c.innerHTML=fn?fn(d):`<div class="empty">Section unavailable.</div>`;bindView();flash()}
function dashboard(d){return `<div class="hero"><div class="kicker">Amaal Telecoms</div><h2 style="margin:6px 0">Business administration</h2><p class="muted">Manage products, inventory, people, security and operating controls from one place.</p></div><div class="grid">${[['Staff',d?.users],['Active locations',d?.activeLocations],['Audit events',d?.auditEvents],['Unread notifications',d?.unreadNotifications]].map(x=>`<div class="card"><div class="label">${esc(x[0])}</div><div class="metric">${num(x[1])}</div></div>`).join('')}</div><div class="grid2"><div class="card"><h3 class="sectiontitle">Catalog</h3><p class="muted">Products, categories, brands, variants, media, pricing, tags and website publishing.</p>${btn('Open products','nav:Products','btn primary')}</div><div class="card"><h3 class="sectiontitle">Inventory</h3><p class="muted">Stock, receiving, transfers, reservations, serialized devices, stocktakes and reconciliation.</p>${btn('Open inventory','nav:Inventory','btn primary')}</div><div class="card"><h3 class="sectiontitle">Security</h3><p class="muted">Authentication, MFA, password policy, sessions, security events and audit controls.</p>${btn('Open security','nav:Security','btn')}</div><div class="card"><h3 class="sectiontitle">Administration</h3><p class="muted">Staff, roles, organization, departments, notifications and system settings.</p>${btn('Open staff','nav:Staff','btn')}</div></div>`}
function inventory(d){return `<div class="grid">${[['Locations',d?.locations],['Stocked SKUs',d?.stockedSkus],['Units on hand',d?.onHand],['Reserved',d?.reserved],['Low stock',d?.lowStock],['Serialized units',d?.serialized],['Movements today',d?.movements24h]].map(x=>`<div class="card"><div class="label">${esc(x[0])}</div><div class="metric">${num(x[1])}</div></div>`).join('')}</div><div class="toolbar">${has('inventory.receive')?btn('Receive stock','receive-stock','btn primary'):''}${has('inventory.adjust')?btn('Adjust stock','adjust-stock'):''}${has('inventory.transfer')?btn('Create transfer','create-transfer'):''}${has('inventory.reserve')?btn('Reserve stock','reserve-stock'):''}${has('inventory.stocktake')?btn('Start stocktake','start-stocktake'):''}${has('inventory.incidents')?btn('Report damage/loss','new-incident'):''}${has('inventory.export')?btn('Export inventory','export-inventory'):''}</div><div class="grid2"><div class="card"><h3 class="sectiontitle">Stock control</h3><p class="muted">Inventory balances are maintained by SKU and location. Stock-changing actions create a traceable movement record.</p></div><div class="card"><h3 class="sectiontitle">Serialized devices</h3><p class="muted">Track phones and other serialized electronics using serial numbers and IMEI records.</p></div></div>`}
function stockView(d){const rows=(d?.rows||[]).map(r=>`<tr><td><b>${esc(r.product_name)}</b><br><span class="muted">${esc(r.brand_name||'')} · ${esc(r.variant_name)}</span></td><td>${esc(r.sku)}</td><td>${esc(r.location_name)}</td><td>${num(r.on_hand)}</td><td>${num(r.reserved)}</td><td>${Number(r.available)<=5?'<span class="bad">':''}${num(r.available)}${Number(r.available)<=5?'</span>':''}</td><td>${r.serialized?'Serialized':'Standard'}</td><td>${money(r.cost_price)}</td></tr>`);return `<div class="toolbar">${btn('Refresh','refresh')}${has('inventory.export')?btn('Export','export-inventory'):''}</div>${table(['Product','SKU','Location','On hand','Reserved','Available','Tracking','Cost'],rows,'No inventory records','Receive stock or create an inventory location to begin.')}`}
function locations(d){return `<div class="toolbar">${has('inventory.manage')?btn('Add location','add-location','btn primary'):''}</div>${table(['Location','Code','Type','Status','SKUs','Units','Address','Actions'],(d||[]).map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${esc(r.code)}</td><td>${esc(r.type)}</td><td>${pill(r.status)}</td><td>${num(r.sku_count)}</td><td>${num(r.total_units)}</td><td>${esc(r.address||'—')}</td><td>${has('inventory.manage')?btn('Edit','edit-location:'+r.id):''}</td></tr>`),'No locations','Create a warehouse, store, service center or other inventory location.')}`}
function receipts(d){return `<div class="toolbar">${has('inventory.receive')?btn('Receive stock','receive-stock','btn primary'):''}</div>${table(['Receipt','Location','Supplier','Reference','Lines','Units','Created'],(d||[]).map(r=>`<tr><td><b>${esc(r.receipt_no)}</b></td><td>${esc(r.location_name)}</td><td>${esc(r.supplier_name||'—')}</td><td>${esc(r.supplier_reference||'—')}</td><td>${num(r.line_count)}</td><td>${num(r.units)}</td><td>${new Date(r.created_at).toLocaleString()}</td></tr>`),'No goods receipts','Received inventory will appear here.')}`}
function adjustments(d){return `<div class="toolbar">${has('inventory.adjust')?btn('New adjustment','adjust-stock','btn primary'):''}</div>${table(['Adjustment','Location','Reason','Lines','Net change','Created'],(d||[]).map(r=>`<tr><td><b>${esc(r.adjustment_no)}</b></td><td>${esc(r.location_name)}</td><td>${esc(r.reason)}</td><td>${num(r.line_count)}</td><td>${num(r.net_change)}</td><td>${new Date(r.created_at).toLocaleString()}</td></tr>`),'No adjustments','Approved stock adjustments will be recorded here.')}`}
function transfers(d){return `<div class="toolbar">${has('inventory.transfer')?btn('Create transfer','create-transfer','btn primary'):''}</div>${table(['Transfer','From','To','Status','Lines','Units','Created','Actions'],(d||[]).map(r=>`<tr><td><b>${esc(r.transfer_no)}</b></td><td>${esc(r.from_location_name)}</td><td>${esc(r.to_location_name)}</td><td>${pill(r.status)}</td><td>${num(r.line_count)}</td><td>${num(r.units)}</td><td>${new Date(r.created_at).toLocaleString()}</td><td class="actions">${r.status==='Submitted'&&has('inventory.transfer')?btn('Approve','approve-transfer:'+r.id):''}${['Submitted','Approved'].includes(r.status)&&has('inventory.transfer')?btn('Ship','ship-transfer:'+r.id):''}${r.status==='Shipped'&&has('inventory.transfer')?btn('Receive','receive-transfer:'+r.id):''}</td></tr>`),'No transfers','Create a transfer when stock moves between locations.')}`}
function reservations(d){return `<div class="toolbar">${has('inventory.reserve')?btn('Reserve stock','reserve-stock','btn primary'):''}</div>${table(['Product','SKU','Location','Quantity','Status','Expires','Created','Actions'],(d||[]).map(r=>`<tr><td>${esc(r.product_name)}<br><span class="muted">${esc(r.variant_name)}</span></td><td>${esc(r.sku)}</td><td>${esc(r.location_name)}</td><td>${num(r.quantity)}</td><td>${pill(r.status)}</td><td>${r.expires_at?new Date(r.expires_at).toLocaleString():'No expiry'}</td><td>${new Date(r.created_at).toLocaleString()}</td><td>${r.status==='Active'&&has('inventory.reserve')?btn('Release','release-reservation:'+r.id):''}</td></tr>`),'No reservations','Reserved stock will appear here.')}`}
function serialized(d){return table(['Product','SKU','Variant','Serial','IMEI 1','IMEI 2','Location','Status','Cost'],(d||[]).map(r=>`<tr><td>${esc(r.product_name)}</td><td>${esc(r.sku)}</td><td>${esc(r.variant_name)}</td><td>${esc(r.serial_number||'—')}</td><td>${esc(r.imei1||'—')}</td><td>${esc(r.imei2||'—')}</td><td>${esc(r.location_name||'—')}</td><td>${pill(r.status)}</td><td>${money(r.unit_cost)}</td></tr>`),'No serialized units','Serialized devices will appear after they are received.')}
function movements(d){return table(['Time','Product','SKU','Location','Type','Quantity','Before','After','Reason','Reference'],(d||[]).map(r=>`<tr><td>${new Date(r.created_at).toLocaleString()}</td><td>${esc(r.product_name)}</td><td>${esc(r.sku)}</td><td>${esc(r.location_name)}</td><td>${pill(r.movement_type)}</td><td>${num(r.quantity)}</td><td>${num(r.before_qty)}</td><td>${num(r.after_qty)}</td><td>${esc(r.reason)}</td><td>${esc(r.reference_type||'')} ${esc(r.reference_id||'')}</td></tr>`),'No stock movements','Every stock-changing operation will create a movement record.')}
function stocktakes(d){return `<div class="toolbar">${has('inventory.stocktake')?btn('Start stocktake','start-stocktake','btn primary'):''}</div>${table(['Stocktake','Location','Status','Lines','Variance','Created','Completed','Actions'],(d||[]).map(r=>`<tr><td><b>${esc(r.stocktake_no)}</b></td><td>${esc(r.location_name)}</td><td>${pill(r.status)}</td><td>${num(r.line_count)}</td><td>${num(r.variance_total)}</td><td>${new Date(r.created_at).toLocaleString()}</td><td>${r.completed_at?new Date(r.completed_at).toLocaleString():'—'}</td><td>${r.status==='In Progress'&&has('inventory.stocktake')?btn('Count / reconcile','open-stocktake:'+r.id):''}</td></tr>`),'No stocktakes','Start a stocktake to reconcile physical counts with system balances.')}`}
function incidents(d){return `<div class="toolbar">${has('inventory.incidents')?btn('Report damage/loss','new-incident','btn primary'):''}</div>${table(['Incident','Type','Product','SKU','Location','Qty','Status','Reason','Created','Actions'],(d||[]).map(r=>`<tr><td><b>${esc(r.incident_no)}</b></td><td>${pill(r.incident_type)}</td><td>${esc(r.product_name)}</td><td>${esc(r.sku)}</td><td>${esc(r.location_name)}</td><td>${num(r.quantity)}</td><td>${pill(r.status)}</td><td>${esc(r.reason)}</td><td>${new Date(r.created_at).toLocaleString()}</td><td>${r.status==='Open'&&has('inventory.incidents')?btn('Resolve','resolve-incident:'+r.id):''}</td></tr>`),'No incidents','Damage, loss, found stock and returns will be recorded here.')}`}
function products(d){const rows=(d?.rows||[]).map(r=>`<tr><td><b>${esc(r.name)}</b><br><span class="muted">${esc(r.product_type)}</span></td><td>${esc(r.brand_name||'—')}</td><td>${esc(r.category_name||'—')}</td><td>${num(r.variant_count)}</td><td>${r.min_price==null?'—':money(r.min_price)}</td><td>${pill(r.status)}</td><td>${pill(r.website_visibility)}</td><td class="actions">${btn('View','view-product:'+r.id)}${has('catalog.manage')?btn('Edit','edit-product:'+r.id):''}${has('catalog.publish')?btn(r.website_visibility==='Published'?'Unpublish':'Publish','publish-product:'+r.id):''}</td></tr>`);return `<div class="grid">${[['Products',d?.summary?.products],['Brands',d?.summary?.brands],['Categories',d?.summary?.categories],['Active variants',d?.summary?.variants],['Published',d?.summary?.published]].map(x=>`<div class="card"><div class="label">${esc(x[0])}</div><div class="metric">${num(x[1])}</div></div>`).join('')}</div><div class="toolbar"><div class="search"><input id="productSearch" placeholder="Search products, brands or SKU" value="${esc(state.productQuery)}">${btn('Search','search-products','btn primary')}</div>${has('catalog.manage')?btn('Add product','add-product','btn primary'):''}${has('catalog.export')?btn('Export catalog','export-catalog'):''}</div>${table(['Product','Brand','Category','Variants','From price','Status','Website','Actions'],rows,'No products','Add your first product to begin building the Amaal Telecoms catalog.')}`}
function categories(d){return `<div class="toolbar">${has('catalog.manage')?btn('Add category','add-category','btn primary'):''}</div>${table(['Category','Parent','Slug','Status','Products','SEO','Actions'],(d||[]).map(r=>`<tr><td><b>${esc(r.name)}</b><br><span class="muted">${esc(r.description||'')}</span></td><td>${esc(r.parent_name||'Root')}</td><td>${esc(r.slug)}</td><td>${pill(r.status)}</td><td>${num(r.product_count)}</td><td>${esc(r.seo_title||'—')}</td><td>${has('catalog.manage')?btn('Edit','edit-category:'+r.id):''}</td></tr>`),'No categories','Create categories such as Phones, TVs, Appliances and Accessories.')}`}
function brands(d){return `<div class="toolbar">${has('catalog.manage')?btn('Add brand','add-brand','btn primary'):''}</div>${table(['Brand','Slug','Products','Status','Website','Actions'],(d||[]).map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${esc(r.slug)}</td><td>${num(r.product_count)}</td><td>${pill(r.status)}</td><td>${esc(r.website_url||'—')}</td><td>${has('catalog.manage')?btn('Edit','edit-brand:'+r.id):''}</td></tr>`),'No brands','Add brands carried by Amaal Telecoms.')}`}
function tags(d){return `<div class="toolbar">${has('catalog.tags')?btn('Add tag','add-tag','btn primary'):''}</div>${table(['Tag','Slug','Created'],(d||[]).map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${esc(r.slug)}</td><td>${new Date(r.created_at).toLocaleString()}</td></tr>`),'No tags','Tags can be used to organize and filter products.')}`}
function staff(d){return `<div class="toolbar">${has('staff.manage')?btn('Add staff','add-staff','btn primary'):''}</div>${table(['Name','Email','Status','Roles','Created','Actions'],(d||[]).map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${esc(r.email)}</td><td>${pill(r.status)}</td><td>${(r.roles||[]).map(esc).join(', ')||'—'}</td><td>${new Date(r.created_at).toLocaleString()}</td><td class="actions">${has('staff.profile.manage')?btn('Profile','profile:'+r.id):''}${has('staff.manage')&&r.id!==state.user?.id?btn(r.status==='Active'?'Suspend':'Activate','toggle-user:'+r.id+':'+r.status):''}</td></tr>`),'No staff accounts','Create staff accounts and assign access through roles.')}`}
function roles(d){return `<div class="toolbar">${has('roles.manage')?btn('Create role','add-role','btn primary'):''}</div>${table(['Role','Description','System','Permissions','Actions'],(d||[]).map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${esc(r.description)}</td><td>${r.system?'Yes':'No'}</td><td>${num((r.permissions||[]).length)}</td><td>${has('roles.manage')&&!r.system?btn('Edit','edit-role:'+r.id):''}</td></tr>`),'No roles','Roles define what staff can access.')}`}
function invitations(d){return `<div class="toolbar">${has('staff.manage')?btn('Invite staff','add-invite','btn primary'):''}</div>${table(['Email','Name','Status','Expires','Created','Actions'],(d||[]).map(r=>`<tr><td>${esc(r.email)}</td><td>${esc(r.name||'—')}</td><td>${pill(r.status)}</td><td>${new Date(r.expires_at).toLocaleString()}</td><td>${new Date(r.created_at).toLocaleString()}</td><td>${r.status==='Pending'&&has('staff.manage')?btn('Revoke','revoke-invite:'+r.id):''}</td></tr>`),'No invitations','Staff invitations will appear here.')}`}
function sessions(d){return table(['User','Email','Created','Last seen','Expires','IP','Actions'],(d||[]).map(r=>`<tr><td>${esc(r.user_name||'—')}</td><td>${esc(r.email||'—')}</td><td>${new Date(r.created_at).toLocaleString()}</td><td>${r.last_seen_at?new Date(r.last_seen_at).toLocaleString():'—'}</td><td>${new Date(r.expires_at).toLocaleString()}</td><td>${esc(r.ip||'—')}</td><td>${has('sessions.manage')?btn('Revoke all','revoke-user-sessions:'+r.user_id):''}</td></tr>`),'No active sessions','Active administrator sessions will appear here.')}
function organization(d){return `<form id="orgForm"><div class="card"><div class="formgrid">${field('Legal name','legalName',d?.legal_name||'')}${field('Trading name','tradingName',d?.trading_name||'')}${field('Registration number','registrationNumber',d?.registration_number||'')}${field('Tax ID','tax_number',d?.tax_number||'')}${field('Email','email',d?.email||'','email')}${field('Phone','phone',d?.phone||'')}${field('Country','country',d?.country||'Uganda')}${field('Currency','currency',d?.currency||'UGX')}${field('Timezone','timezone',d?.timezone||'Africa/Kampala')}${field('Website','website',d?.website||'','url')}${area('Address','address',d?.address||'')}${area('Description','description',d?.description||'')}</div><div class="toolbar">${has('organization.manage')?btn('Save organization','save-org','btn primary'):''}</div></div></form>`}
function departments(d){return `<div class="toolbar">${has('departments.manage')?btn('Add department','add-dept','btn primary'):''}</div>${table(['Name','Code','Description','Status','Created','Actions'],(d||[]).map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${esc(r.code||'—')}</td><td>${esc(r.description||'')}</td><td>${pill(r.status)}</td><td>${new Date(r.created_at).toLocaleString()}</td><td>${has('departments.manage')?btn('Edit','edit-dept:'+r.id):''}</td></tr>`),'No departments','Create departments for staff organization.')}`}
function audit(d){return `<div class="toolbar">${has('audit.export')?btn('Export audit log','export-audit'):''}${btn('Refresh','refresh')}</div>${table(['Time','Actor','Action','Resource','Detail','IP'],(d||[]).map(r=>`<tr><td>${new Date(r.created_at).toLocaleString()}</td><td>${esc(r.actor_email||'System')}</td><td>${esc(r.action)}</td><td>${esc(r.resource_type)} ${esc(r.resource_id||'')}</td><td>${esc(r.detail)}</td><td>${esc(r.ip||'—')}</td></tr>`),'No audit events','Administrative actions will appear here.')}`}
function notifications(d){return `<div class="toolbar">${has('notifications.manage')?btn('Create notification','add-notification','btn primary'):''}</div>${table(['Title','Message','Audience','Status','Created','Actions'],(d||[]).map(r=>`<tr><td><b>${esc(r.title)}</b></td><td>${esc(r.body)}</td><td>${r.user_id?'Specific user':'All administrators'}</td><td>${r.read_at?pill('Read'):pill('Unread')}</td><td>${new Date(r.created_at).toLocaleString()}</td><td>${!r.read_at?btn('Mark read','read-notification:'+r.id):''}</td></tr>`),'No notifications','System notifications will appear here.')}`}
function settings(d){const get=k=>d?.[k];return `<form id="settingsForm"><div class="card"><h3 class="sectiontitle">General settings</h3><div class="formgrid">${field('Currency','currency',get('currency')||'UGX')}${field('Timezone','timezone',get('timezone')||'Africa/Kampala')}${field('Session duration (minutes)','sessionMinutes',get('sessionMinutes')||720,'number')}${field('Idle timeout (minutes)','idleTimeoutMinutes',get('idleTimeoutMinutes')||30,'number')}${field('Audit retention (days)','auditRetentionDays',get('auditRetentionDays')||3650,'number')}${field('Company name','companyName',get('companyName')||'Amaal Telecoms')}${field('Company email','companyEmail',get('companyEmail')||'','email')}${field('Company phone','companyPhone',get('companyPhone')||'')}</div><div class="toolbar">${has('settings.manage')?btn('Save settings','save-settings','btn primary'):''}</div></div></form>`}
function featureFlags(d){return `<div class="card"><p class="muted">Feature controls let authorized administrators enable or disable optional capabilities.</p>${table(['Feature','Enabled','Description','Action'],(d||[]).map(r=>`<tr><td><b>${esc(r.key)}</b></td><td>${pill(r.enabled?'Enabled':'Disabled')}</td><td>${esc(r.description||'')}</td><td>${has('featureflags.manage')?btn(r.enabled?'Disable':'Enable','toggle-flag:'+r.key+':'+r.enabled):''}</td></tr>`),'No feature flags','Optional system features will appear here.')}</div>`}
function security(d){return `<div class="grid" id="securitySummary"><div class="card"><div class="label">Security status</div><div class="metric">Protected</div></div></div><div class="grid2"><div class="card"><h3 class="sectiontitle">Security policy</h3><form id="securityForm"><div class="formgrid">${field('Maximum login attempts','maxLoginAttempts',d?.maxLoginAttempts||5,'number')}${field('Lockout duration (minutes)','lockoutMinutes',d?.lockoutMinutes||15,'number')}${field('Session duration (minutes)','sessionMinutes',d?.sessionMinutes||720,'number')}${field('Minimum password length','passwordMinLength',d?.passwordMinLength||12,'number')}${field('Idle timeout (minutes)','idleTimeoutMinutes',d?.idleTimeoutMinutes||30,'number')}${field('Audit retention (days)','auditRetentionDays',d?.auditRetentionDays||3650,'number')}${select('Require MFA','mfaRequired',String(Boolean(d?.mfaRequired)),[['true','Yes'],['false','No']])}${select('Require uppercase','passwordRequireUpper',String(Boolean(d?.passwordRequireUpper)),[['true','Yes'],['false','No']])}${select('Require number','passwordRequireNumber',String(Boolean(d?.passwordRequireNumber)),[['true','Yes'],['false','No']])}${select('Require symbol','passwordRequireSymbol',String(Boolean(d?.passwordRequireSymbol)),[['true','Yes'],['false','No']])}</div><div class="toolbar">${has('security.manage')?btn('Save policy','save-security','btn primary'):''}${btn('Change password','change-password')}${btn('MFA setup','setup-mfa')}${btn('Disable MFA','disable-mfa')}</div></form></div><div class="card"><h3 class="sectiontitle">Recent security events</h3><div id="securityEvents" class="spinner">Loading security events…</div></div></div>`}
function productDetail(d){const variants=d?.variants||[];const images=d?.images||[];return `<div class="grid2"><div><div class="card"><div class="kicker">Product</div><h3>${esc(d.name)}</h3><p class="muted">${esc(d.short_description||'')}</p><div class="statline"><span>Status</span>${pill(d.status)}</div><div class="statline"><span>Website</span>${pill(d.website_visibility)}</div><div class="statline"><span>Brand</span><span>${esc(d.brand_name||'—')}</span></div><div class="statline"><span>Category</span><span>${esc(d.category_name||'—')}</span></div><div class="statline"><span>SEO title</span><span>${esc(d.seo_title||'—')}</span></div></div></div><div><div class="card"><h3 class="sectiontitle">Variants / SKUs</h3>${variants.length?table(['SKU','Variant','Price','Wholesale','Serialized','Status','Actions'],variants.map(v=>`<tr><td>${esc(v.sku)}</td><td>${esc(v.variant_name)}</td><td>${money(v.selling_price)}</td><td>${v.wholesale_price==null?'—':money(v.wholesale_price)}</td><td>${v.serialized?'Yes':'No'}</td><td>${pill(v.status)}</td><td>${has('catalog.manage')?btn('Edit','edit-variant:'+v.id):''}${btn('Price history','price-history:'+v.id)}</td></tr>`)): '<div class="empty">No variants yet.</div>'}</div></div></div><div class="subsection card"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><h3 class="sectiontitle">Product media</h3>${has('catalog.manage')?btn('Add image','add-image:'+d.id,'btn primary'):''}</div>${images.length?table(['Preview','Alt text','Order','Primary','Actions'],images.map(i=>`<tr><td><img src="${esc(i.url)}" alt="${esc(i.alt_text)}" style="width:58px;height:58px;object-fit:cover;border-radius:8px;background:#f1f5f9" onerror="this.style.display='none'"></td><td>${esc(i.alt_text||'—')}</td><td>${i.sort_order}</td><td>${i.is_primary?'Yes':'No'}</td><td class="actions">${has('catalog.manage')?btn('Edit','edit-image:'+i.id):''}${has('catalog.manage')?btn('Delete','delete-image:'+i.id,'btn danger'):''}</td></tr>`)):'<div class="empty">No product images yet.</div>'}</div><div class="subsection card"><h3 class="sectiontitle">Actions</h3><div class="toolbar">${has('catalog.manage')?btn('Add variant','add-variant:'+d.id,'btn primary'):''}${has('catalog.tags')?btn('Manage tags','manage-tags:'+d.id):''}${has('catalog.publish')?btn(d.website_visibility==='Published'?'Unpublish':'Publish','publish-product:'+d.id):''}</div></div>`}
async function loadSecurityExtras(){try{const sm=await api('/security/summary');const el=$('#securitySummary');if(el)el.innerHTML=[['Failed sign-ins (24h)',sm.failedLogins24h],['Active sessions',sm.activeSessions],['Locked accounts',sm.lockedAccounts],['MFA users',sm.mfaUsers]].map(x=>`<div class="card"><div class="label">${esc(x[0])}</div><div class="metric">${num(x[1])}</div></div>`).join('');const ev=await api('/security/events?limit=50');const se=$('#securityEvents');if(se)se.innerHTML=table(['Time','User','Result','Reason','IP'],ev.map(r=>`<tr><td>${new Date(r.created_at).toLocaleString()}</td><td>${esc(r.user_name||r.email||'—')}</td><td>${r.success?'<span class="ok">Success</span>':'<span class="bad">Failed</span>'}</td><td>${esc(r.reason)}</td><td>${esc(r.ip||'—')}</td></tr>`),'No recent security events','Authentication activity will appear here.')}catch(e){const se=$('#securityEvents');if(se)se.innerHTML=`<div class="error">${esc(e.message)}</div>`}}

function procurement(d){return `<div class="hero"><div class="kicker">Suppliers & Procurement</div><h2 style="margin:6px 0">Supplier-to-payment control</h2><p class="muted">Manage suppliers, requisitions, purchase orders, receiving, supplier invoices, payments, cost history and performance from one auditable workflow.</p></div><div class="grid">${[['Active suppliers',d?.activeSuppliers],['Pending requisitions',d?.pendingRequisitions],['Open purchase orders',d?.openPurchaseOrders],['Receipts · 30 days',d?.receipts30d]].map(x=>`<div class="card"><div class="label">${esc(x[0])}</div><div class="metric">${num(x[1])}</div></div>`).join('')}</div><div class="grid2"><div class="card"><h3 class="sectiontitle">Supplier finance</h3><div class="statline"><span>Invoiced value</span><b>${money(d?.invoicedValue)}</b></div><div class="statline"><span>Paid · last 30 days</span><b>${money(d?.paid30d)}</b></div><div class="statline"><span>Overdue invoices</span><b>${num(d?.overdueInvoices)}</b></div></div><div class="card"><h3 class="sectiontitle">Workflow</h3><p class="muted">Requisition → approval → purchase order → approval → goods receipt → three-way invoice matching → payment.</p><div class="actions">${btn('Suppliers','nav:Suppliers','btn primary')}${btn('Requisitions','nav:Requisitions')}${btn('Purchase orders','nav:Purchase Orders')}${btn('Invoices','nav:Supplier Invoices')}</div></div></div>`}
function suppliers(rows){rows=rows||[];return `<div class="toolbar">${has('suppliers.manage')?btn('Add supplier','add-supplier','btn primary'):''}${has('procurement.export')?btn('Export suppliers','export-procurement'):''}<div class="search"><input id="supplierSearch" value="${esc(state.supplierQuery||'')}" placeholder="Search supplier, code or email"><button class="btn" data-action="search-suppliers">Search</button></div></div>${table(['Supplier','Country','Currency','Terms','Products','Orders','Status','Actions'],rows.map(r=>`<tr><td><b>${esc(r.legal_name)}</b><br><span class="muted">${esc(r.supplier_code)}</span>${r.trading_name?`<br><span class="muted">${esc(r.trading_name)}</span>`:''}</td><td>${esc(r.country)}</td><td>${esc(r.default_currency)}</td><td>${num(r.payment_terms_days)} days</td><td>${num(r.product_count)}</td><td>${num(r.purchase_order_count)}</td><td>${pill(r.status)}</td><td class="actions">${btn('Open','supplier:'+r.id)}${has('suppliers.manage')?btn('Edit','edit-supplier:'+r.id):''}</td></tr>`),'No suppliers yet','Add your first supplier to begin procurement management.')}`}
function requisitions(rows){rows=rows||[];return `<div class="toolbar">${has('procurement.requisition')?btn('New requisition','add-requisition','btn primary'):''}</div>${table(['Requisition','Requester','Department','Priority','Needed by','Status','Lines','Actions'],rows.map(r=>`<tr><td><b>${esc(r.requisition_no)}</b><br><span class="muted">${new Date(r.created_at).toLocaleString()}</span></td><td>${esc(r.requester_name||'—')}</td><td>${esc(r.department_name||'—')}</td><td>${pill(r.priority)}</td><td>${esc(r.needed_by||'—')}</td><td>${pill(r.status)}</td><td>${num(r.line_count)}</td><td class="actions">${btn('Open','requisition:'+r.id)}${r.status==='Draft'&&has('procurement.requisition')?btn('Edit','edit-requisition:'+r.id):''}${r.status==='Draft'&&has('procurement.requisition')?btn('Submit','submit-requisition:'+r.id):''}${r.status==='Submitted'&&has('procurement.approve')?btn('Approve','approve-requisition:'+r.id):''}${r.status==='Submitted'&&has('procurement.approve')?btn('Reject','reject-requisition:'+r.id,'btn danger'):''}</td></tr>`),'No requisitions yet','Create a requisition from an actual purchasing need.')}`}
function purchaseOrders(rows){rows=rows||[];return `<div class="toolbar">${has('procurement.manage')?btn('New purchase order','add-po','btn primary'):''}</div>${table(['PO','Supplier','Requisition','Status','Currency','Subtotal','Received','Expected','Actions'],rows.map(r=>`<tr><td><b>${esc(r.po_no)}</b></td><td>${esc(r.supplier_name)}</td><td>${esc(r.requisition_no||'—')}</td><td>${pill(r.status)}</td><td>${esc(r.currency)}</td><td>${money(r.subtotal)}</td><td>${num(r.received_units)} / ${num(r.line_count)}</td><td>${esc(r.expected_date||'—')}</td><td class="actions">${btn('Open','po:'+r.id)}${r.status==='Draft'&&has('procurement.manage')?btn('Edit','edit-po:'+r.id):''}${r.status==='Draft'&&has('procurement.manage')?btn('Submit','submit-po:'+r.id):''}${r.status==='Submitted'&&has('procurement.approve')?btn('Approve','approve-po:'+r.id):''}${['Approved','Partially Received'].includes(r.status)&&has('procurement.receive')?btn('Receive','receive-po:'+r.id):''}</td></tr>`),'No purchase orders yet','Create purchase orders from approved purchasing needs.')}`}
function goodsReceipts(rows){rows=rows||[];return `<div class="toolbar">${has('procurement.receive')?btn('Receive against PO','add-grn','btn primary'):''}</div>${table(['GRN','PO','Supplier','Location','Status','Units','Received by','Date'],rows.map(r=>`<tr><td><b>${esc(r.grn_no)}</b></td><td>${esc(r.po_no)}</td><td>${esc(r.supplier_name)}</td><td>${esc(r.location_name)}</td><td>${pill(r.status)}</td><td>${num(r.received_units)}</td><td>${esc(r.received_by_email||'—')}</td><td>${new Date(r.created_at).toLocaleString()}</td></tr>`),'No goods receipts yet','Posted receipts will update inventory and the purchase order lifecycle.')}`}
function supplierInvoices(rows){rows=rows||[];return `<div class="toolbar">${has('procurement.invoice')?btn('Add supplier invoice','add-invoice','btn primary'):''}</div>${table(['Invoice','Supplier','PO','Status','Total','Paid','Due','Actions'],rows.map(r=>`<tr><td><b>${esc(r.invoice_no)}</b></td><td>${esc(r.supplier_name)}</td><td>${esc(r.po_no||'—')}</td><td>${pill(r.status)}</td><td>${money(r.total_amount)}</td><td>${money(r.paid_amount)}</td><td>${esc(r.due_date||'—')}</td><td class="actions">${btn('Open','invoice:'+r.id)}${r.status==='Draft'&&has('procurement.invoice')?btn('Match','match-invoice:'+r.id):''}${['Matched','Partially Paid'].includes(r.status)&&has('procurement.payments')?btn('Pay','pay-invoice:'+r.id):''}${['Draft','Matched','Partially Paid'].includes(r.status)&&has('procurement.invoice')?btn('Dispute','dispute-invoice:'+r.id,'btn danger'):''}</td></tr>`),'No supplier invoices yet','Supplier invoices are real records and can be matched to purchase orders and receipts.')}`}
function supplierPayments(rows){rows=rows||[];return `<div class="toolbar">${has('procurement.payments')?btn('Record payment','add-payment','btn primary'):''}</div>${table(['Payment','Supplier','Invoice','Amount','Method','Reference','Date','Status'],rows.map(r=>`<tr><td><b>${esc(r.payment_no)}</b></td><td>${esc(r.supplier_name)}</td><td>${esc(r.invoice_no||'Unallocated')}</td><td>${money(r.amount)} ${esc(r.currency)}</td><td>${esc(r.method)}</td><td>${esc(r.reference||'—')}</td><td>${esc(r.payment_date)}</td><td>${pill(r.status)}</td></tr>`),'No supplier payments yet','Payments will appear here only after an actual payment is recorded.')}`}
function jsonLinesField(label,name,placeholder){return `<div class="field span2"><label>${esc(label)}</label><textarea name="${esc(name)}" placeholder='${esc(placeholder)}' style="min-height:150px"></textarea><div class="muted" style="font-size:11px;margin-top:5px">Use JSON array format. Example: [{"variantId":"UUID","quantity":1,"unitPrice":100000}]</div></div>`}
async function procurementOptions(){const [sup,vars,depts,locs]=await Promise.all([api('/suppliers?limit=200'),api('/catalog/variants?limit=200&offset=0'),api('/departments'),api('/inventory/locations')]);return {sup,vars,depts,locs}}
function optionPairs(rows,id,name){return (rows||[]).map(x=>[x[id],x[name]])}
async function openSupplier(id){const s=await api('/suppliers/'+id);const body=modal('Supplier profile',`<div class="grid2"><div class="card"><div class="label">Legal name</div><b>${esc(s.legal_name)}</b><div class="muted">${esc(s.supplier_code)}</div></div><div class="card"><div class="label">Status</div>${pill(s.status)}<div class="muted" style="margin-top:8px">${esc(s.country)} · ${esc(s.default_currency)} · ${num(s.payment_terms_days)} days</div></div></div><div class="subsection"><h3 class="sectiontitle">Contacts</h3>${table(['Name','Title','Email','Phone','Primary'],(s.contacts||[]).map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.job_title||'—')}</td><td>${esc(x.email||'—')}</td><td>${esc(x.phone||'—')}</td><td>${x.is_primary?'Yes':'—'}</td></tr>`),'No contacts','Add supplier contacts when available.')}</div><div class="subsection"><h3 class="sectiontitle">Addresses</h3>${table(['Label','Address','City','Region','Country','Primary'],(s.addresses||[]).map(x=>`<tr><td>${esc(x.label)}</td><td>${esc(x.address_line1)} ${esc(x.address_line2)}</td><td>${esc(x.city)}</td><td>${esc(x.region)}</td><td>${esc(x.country)}</td><td>${x.is_primary?'Yes':'—'}</td></tr>`),'No addresses','Add supplier addresses when available.')}</div><div class="subsection"><h3 class="sectiontitle">Product pricing</h3>${table(['Product','SKU','Supplier SKU','Cost','Currency','MOQ','Lead time'],(s.products||[]).map(x=>`<tr><td>${esc(x.product_name)}</td><td>${esc(x.sku)}</td><td>${esc(x.supplier_sku||'—')}</td><td>${money(x.unit_cost)}</td><td>${esc(x.currency)}</td><td>${num(x.min_order_qty)}</td><td>${num(x.lead_time_days)} days</td></tr>`),'No supplier pricing','Supplier-specific product pricing history will appear here.')}</div><div class="subsection"><h3 class="sectiontitle">Performance</h3>${table(['Period','Quality','Delivery','Price','Service','Overall'],(s.performance||[]).map(x=>`<tr><td>${esc(x.review_period_start)} → ${esc(x.review_period_end)}</td><td>${num(x.quality_score)}</td><td>${num(x.delivery_score)}</td><td>${num(x.price_score)}</td><td>${num(x.service_score)}</td><td><b>${num(x.overall_score)}</b></td></tr>`),'No performance reviews','Record supplier performance after real procurement activity.')}</div><div class="toolbar" style="justify-content:flex-end"><button class="btn" data-action="add-supplier-contact:${id}">Add contact</button><button class="btn" data-action="add-supplier-address:${id}">Add address</button><button class="btn" data-action="add-supplier-document:${id}">Add document</button><button class="btn" data-action="add-supplier-price:${id}">Add product price</button><button class="btn" data-action="add-supplier-performance:${id}">Record performance</button></div>`);return body}


function salesView(d){const s=d?.summary||{};const rows=d?.sales||d||[];return `<div class="hero"><div class="kicker">Sales & POS</div><h2 style="margin:6px 0">Point of Sale</h2><p class="muted">Process retail sales, capture payments, link customers and automatically deduct inventory.</p><div class="actions">${has('sales.create')?btn('New sale','new-sale','btn primary'):''}${has('sales.export')?btn('Export sales','export-sales'):''}</div></div><div class="grid">${[['Today',money(s.today?.total)],['Transactions today',num(s.today?.count)],['Units sold today',num(s.unitsToday)],['This month',money(s.month?.total)],['Monthly transactions',num(s.month?.count)],['Payment methods today',num((s.payments||[]).length)]].map(x=>`<div class="card"><div class="label">${esc(x[0])}</div><div class="metric" style="font-size:22px">${esc(x[1])}</div></div>`).join('')}</div><div class="grid2"><div class="card"><h3 class="sectiontitle">Today's payment mix</h3>${table(['Method','Amount'],(s.payments||[]).map(p=>`<tr><td>${esc(p.method)}</td><td>${money(p.amount)}</td></tr>`),'No payments today','Completed sales will appear here.')}</div><div class="card"><h3 class="sectiontitle">Sales register</h3><p class="muted">Review completed and voided transactions. Opening a sale shows its lines, payments, serial/IMEI information and audit history.</p></div></div>${table(['Sale','Customer','Location','Units','Total','Status','Cashier','Date','Actions'],rows.map(r=>`<tr><td><b>${esc(r.sale_no)}</b></td><td>${esc(r.customer_name||'Walk-in')}</td><td>${esc(r.location_name)}</td><td>${num(r.units)}</td><td>${money(r.grand_total)}</td><td>${pill(r.status)}</td><td>${esc(r.cashier_email)}</td><td>${new Date(r.created_at).toLocaleString()}</td><td class="actions">${btn('Open','sale:'+r.id)}${r.status==='Completed'&&has('sales.void')?btn('Void','void-sale:'+r.id):''}</td></tr>`),'No sales yet','Completed sales will appear here.')}`}
function posTotal(){return state.posCart.reduce((a,x)=>a+Number(x.lineTotal||0),0)}
function renderPosModal(){const locations=state.cache.locations||[];const customersData=state.cache.posCustomers||[];const m=modal('New Sale',`<div class="grid2"><div><div class="field"><label>Selling location</label><select id="posLocation">${locations.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Customer</label><select id="posCustomer"><option value="">Walk-in customer</option>${customersData.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${esc(x.phone||x.customer_no)}</option>`).join('')}</select></div><div class="field"><label>Find product</label><input id="posSearch" placeholder="Search product, SKU or barcode"><div class="toolbar"><button type="button" class="btn" id="posSearchBtn">Search</button></div></div><div id="posResults"></div></div><div><h3 class="sectiontitle">Cart</h3><div id="posCart">${posCartHtml()}</div><div class="card"><div class="statline"><span>Total</span><b id="posGrandTotal">${money(posTotal())}</b></div></div><div class="subsection"><h3 class="sectiontitle">Payment</h3><div id="posPayments">${posPaymentsHtml()}</div><button type="button" class="btn" id="posAddPayment">Add payment</button></div><div id="posMsg"></div><div class="toolbar" style="justify-content:flex-end"><button type="button" class="btn" id="posCancel">Cancel</button><button type="button" class="btn primary" id="posCheckout">Complete sale</button></div></div></div>`);const loc=$('#posLocation');state.posLocation=loc?.value||'';loc.onchange=()=>{state.posLocation=loc.value;state.posCart=[];document.querySelector('#posCart').innerHTML=posCartHtml();};$('#posCancel').onclick=()=>m.closest('.modal').remove();$('#posSearchBtn').onclick=posSearch;$('#posSearch').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();posSearch()}};$('#posAddPayment').onclick=()=>{state.posPayments.push({method:'Cash',amount:Math.max(0,round2(posTotal()-state.posPayments.reduce((a,p)=>a+Number(p.amount||0),0))),reference:''});document.querySelector('#posPayments').innerHTML=posPaymentsHtml()};$('#posCheckout').onclick=posCheckout;bindPosButtons();return m}
function posCartHtml(){if(!state.posCart.length)return `<div class="empty"><strong>Cart is empty</strong>Add products from the search results.</div>`;return table(['Product','Qty','Unit','Tax','Total',''],state.posCart.map((x,i)=>`<tr><td><b>${esc(x.productName)}</b><br><span class="muted">${esc(x.sku)}${x.serialized?' · Serialized':''}</span></td><td>${x.serialized?1:`<input data-pos-qty="${i}" value="${esc(x.quantity)}" type="number" min="0.001" step="0.001" style="width:80px">`}</td><td>${money(x.unitPrice)}</td><td>${money(x.taxAmount)}</td><td>${money(x.lineTotal)}</td><td>${btn('Remove','pos-remove:'+i)}</td></tr>`),'Cart empty','Add a product to begin.')}
function posPaymentsHtml(){if(!state.posPayments.length)return `<div class="empty">No payment recorded yet.</div>`;return table(['Method','Amount','Reference',''],state.posPayments.map((p,i)=>`<tr><td><select data-pay-method="${i}">${['Cash','Mobile Money','Card','Bank Transfer','Online Payment'].map(x=>`<option ${x===p.method?'selected':''}>${x}</option>`).join('')}</select></td><td><input data-pay-amount="${i}" type="number" min="0.01" step="0.01" value="${esc(p.amount)}" style="width:110px"></td><td><input data-pay-ref="${i}" value="${esc(p.reference||'')}" placeholder="Optional reference"></td><td>${btn('Remove','pos-pay-remove:'+i)}</td></tr>`),'No payments','Add a payment method.')}
async function posSearch(){try{const q=encodeURIComponent($('#posSearch')?.value||'');const locationId=$('#posLocation')?.value||'';const rows=await api(`/sales/products?q=${q}&locationId=${encodeURIComponent(locationId)}&limit=30`);$('#posResults').innerHTML=table(['Product','SKU','Available','Price','Type',''],rows.map(x=>`<tr><td><b>${esc(x.product_name)}</b><br><span class="muted">${esc(x.variant_name||'')}</span></td><td>${esc(x.sku)}</td><td>${num(x.available)}</td><td>${money(x.selling_price)}</td><td>${x.serialized?'Serialized':'Standard'}</td><td>${Number(x.available)>0||!x.track_inventory?btn('Add','pos-add:'+x.variant_id):pill('Out of stock')}</td></tr>`),'No matching products','Try a product name, SKU or barcode.');document.querySelectorAll('[data-action^="pos-add:"]').forEach(b=>b.onclick=()=>posAdd(b.dataset.action.split(':')[1]));}catch(e){$('#posResults').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
async function posAdd(variantId){try{const v=await api(`/sales/product/${variantId}?locationId=${encodeURIComponent($('#posLocation').value)}`);if(!v)throw Error('Product is unavailable');if(v.serialized){const serials=await api(`/sales/serials/${variantId}?locationId=${encodeURIComponent($('#posLocation').value)}`);if(!serials.length)throw Error('No available serialized unit at this location');const pick=prompt(`Enter the serial/IMEI number to sell:\n${serials.map(x=>[x.serial_number,x.imei1,x.imei2].filter(Boolean).join(' / ')).join('\n')}`);const su=serials.find(x=>[x.serial_number,x.imei1,x.imei2].includes(pick));if(!su)throw Error('That serial/IMEI is not available');state.posCart.push({variantId:v.variant_id,productName:v.product_name,sku:v.sku,serialized:true,quantity:1,unitPrice:Number(v.selling_price),taxRate:Number(v.tax_rate||0),discountAmount:0,serials:[su.id]});}else{const existing=state.posCart.find(x=>x.variantId===variantId);if(existing){existing.quantity=round2(Number(existing.quantity)+1)}else state.posCart.push({variantId:v.variant_id,productName:v.product_name,sku:v.sku,serialized:false,quantity:1,unitPrice:Number(v.selling_price),taxRate:Number(v.tax_rate||0),discountAmount:0,serials:[]});}recalcPos();$('#posCart').innerHTML=posCartHtml();bindPosButtons();}catch(e){$('#posMsg').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
function recalcPos(){for(const x of state.posCart){const base=Math.max(0,round2(Number(x.unitPrice)*Number(x.quantity)-Number(x.discountAmount||0)));x.taxAmount=round2(base*Number(x.taxRate||0)/100);x.lineTotal=round2(base+x.taxAmount)}$('#posGrandTotal').textContent=money(posTotal())}
function bindPosButtons(){document.querySelectorAll('[data-pos-qty]').forEach(i=>i.onchange=()=>{const n=Number(i.value);if(n>0)state.posCart[Number(i.dataset.posQty)].quantity=n;recalcPos();$('#posCart').innerHTML=posCartHtml();bindPosButtons()});document.querySelectorAll('[data-pay-method]').forEach(i=>i.onchange=()=>state.posPayments[Number(i.dataset.payMethod)].method=i.value);document.querySelectorAll('[data-pay-amount]').forEach(i=>i.onchange=()=>{state.posPayments[Number(i.dataset.payAmount)].amount=Number(i.value);});document.querySelectorAll('[data-pay-ref]').forEach(i=>i.onchange=()=>state.posPayments[Number(i.dataset.payRef)].reference=i.value);document.querySelectorAll('[data-action^="pos-remove:"]').forEach(b=>b.onclick=()=>{state.posCart.splice(Number(b.dataset.action.split(':')[1]),1);recalcPos();$('#posCart').innerHTML=posCartHtml();bindPosButtons()});document.querySelectorAll('[data-action^="pos-pay-remove:"]').forEach(b=>b.onclick=()=>{state.posPayments.splice(Number(b.dataset.action.split(':')[1]),1);document.querySelector('#posPayments').innerHTML=posPaymentsHtml();bindPosButtons()})}
async function posCheckout(){try{recalcPos();if(!state.posCart.length)throw Error('Cart is empty');const loc=$('#posLocation').value;if(!loc)throw Error('Select a selling location');const payments=state.posPayments.map(p=>({method:p.method,amount:Number(p.amount),reference:p.reference||''}));if(!payments.length)throw Error('Add at least one payment');const d=await api('/sales',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID?crypto.randomUUID():String(Date.now())},body:JSON.stringify({locationId:loc,customerId:$('#posCustomer').value||null,lines:state.posCart,payments,currency:'UGX'})});state.posCart=[];state.posPayments=[];document.querySelector('.modal')?.remove();state.message=`Sale ${d.sale_no} completed successfully`;await load('Sales');showSale(d)}catch(e){$('#posMsg').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
function showSale(d){const body=modal('Sale details',`<div class="grid2"><div class="card"><div class="label">Sale</div><b>${esc(d.sale_no)}</b><p>${pill(d.status)}</p></div><div class="card"><div class="label">Customer</div><b>${esc(d.customer_name||'Walk-in customer')}</b><p class="muted">${esc(d.location_name)}</p></div></div>${table(['Product','SKU','Qty','Unit','Tax','Total','Serial/IMEI'],(d.lines||[]).map(x=>`<tr><td>${esc(x.product_name)}</td><td>${esc(x.sku)}</td><td>${num(x.quantity)}</td><td>${money(x.unit_price)}</td><td>${money(x.tax_amount)}</td><td>${money(x.line_total)}</td><td>${(x.serial_units||[]).map(s=>esc([s.serialNumber,s.imei1,s.imei2].filter(Boolean).join(' / '))).join('<br>')||'—'}</td></tr>`),'No lines','') }<div class="card"><div class="statline"><span>Total</span><b>${money(d.grand_total)}</b></div><div class="statline"><span>Payments</span><b>${(d.payments||[]).map(p=>`${esc(p.method)} ${money(p.amount)}`).join(' · ')}</b></div></div><div class="toolbar" style="justify-content:flex-end">${has('sales.void')&&d.status==='Completed'?btn('Void sale','void-sale:'+d.id):''}<button class="btn primary" id="printSale">Print receipt</button></div>`);body.querySelector('#printSale').onclick=()=>printSale(d) ;return body}
function printSale(d){const w=window.open('','_blank','width=420,height=700');if(!w)return;w.document.write(`<html><head><title>${esc(d.sale_no)}</title><style>body{font-family:Arial;padding:24px;max-width:360px;margin:auto}h1{font-size:22px}.line{display:flex;justify-content:space-between;gap:10px;border-bottom:1px solid #ddd;padding:8px 0}.total{font-size:20px;font-weight:bold;margin-top:14px}</style></head><body><h1>Amaal Telecoms</h1><div>Receipt: ${esc(d.sale_no)}</div><div>${new Date(d.completed_at||d.created_at).toLocaleString()}</div>${(d.lines||[]).map(x=>`<div class="line"><span>${esc(x.product_name)} × ${num(x.quantity)}</span><span>${money(x.line_total)}</span></div>`).join('')}<div class="total">Total: ${money(d.grand_total)}</div><p>Payment: ${(d.payments||[]).map(p=>esc(p.method)+' '+money(p.amount)).join(', ')}</p><p>Thank you for shopping with Amaal Telecoms.</p><script>window.print()</script></body></html>`);w.document.close()}
function bindView(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action,b));if(state.view==='Security')loadSecurityExtras()}
async function inventoryTransactionModal(title,type){try{const [variants,locs]=await Promise.all([api('/catalog/variants'),ensureData('locations')]);const vopts=variants.map(v=>[v.id,`${v.sku} — ${v.product_name} — ${v.variant_name}`]);const lopts=locs.map(l=>[l.id,l.name]);if(!vopts.length)throw Error('Create at least one product SKU before recording inventory.');if(!lopts.length)throw Error('Create an inventory location first.');let fields=[];if(type==='receive'){fields=[select('Receiving location','locationId',lopts[0][0],lopts),field('Supplier','supplierName'),field('Supplier reference','supplierReference'),area('Notes','notes')]}else if(type==='adjust'){fields=[select('Location','locationId',lopts[0][0],lopts),area('Reason','reason','','required')]}else if(type==='transfer'){fields=[select('From location','fromLocationId',lopts[0][0],lopts),select('To location','toLocationId',lopts[1]?.[0]||lopts[0][0],lopts),area('Notes','notes')]}else{fields=[select('Location','locationId',lopts[0][0],lopts),field('Reference type','referenceType'),field('Reference ID','referenceId'),field('Expiry','expiresAt','','datetime-local')]}fields.push(select('Product SKU','variantId',vopts[0][0],vopts),field(type==='adjust'?'Quantity change':'Quantity','quantity','1','number','min="0.001" step="0.001"'),field('Unit cost (UGX)','unitCost','0','number','min="0" step="0.01"'));if(type==='receive'||type==='transfer')fields.push(area('Serial / IMEI records (JSON)','serials','[]','placeholder="[{\"serialNumber\":\"...\",\"imei1\":\"...\"}]"'));return formModal(title,fields,async x=>{let serials=[];try{serials=JSON.parse(x.serials||'[]')}catch{throw Error('Serial / IMEI JSON is invalid')}const line={variantId:x.variantId,quantity:Number(x.quantity),quantityChange:Number(x.quantity),unitCost:Number(x.unitCost),serials};if(type==='receive')return api('/inventory/receipts',{method:'POST',body:JSON.stringify({...x,lines:[line]})});if(type==='adjust')return api('/inventory/adjustments',{method:'POST',body:JSON.stringify({...x,lines:[line]})});if(type==='transfer'){if(x.fromLocationId===x.toLocationId)throw Error('From and To locations must be different.');return api('/inventory/transfers',{method:'POST',body:JSON.stringify({...x,lines:[line]})});}return api('/inventory/reservations',{method:'POST',body:JSON.stringify(x)})},'Create')}catch(e){state.error=e.message;flash()}}
async function openStocktake(id){const d=await api('/inventory/stocktakes/'+id);const fields=[];for(const l of (d.lines||[])){fields.push(`<div class="card span2" style="margin-bottom:8px"><b>${esc(l.product_name)}</b><div class="muted">${esc(l.sku)} · ${esc(l.variant_name)} · System quantity: ${num(l.system_qty)}</div>${field('Counted quantity','count_'+l.variant_id,l.counted_qty??'','number','min="0" step="0.001"')}${field('Variance reason','reason_'+l.variant_id,l.reason||'')}</div>`)}const body=modal('Stocktake reconciliation',`<form id="stocktakeForm"><div class="formgrid">${fields.join('')}</div><div id="formMsg"></div><div class="toolbar" style="justify-content:flex-end"><button type="button" class="btn" data-close>Cancel</button><button class="btn">Save counts</button><button type="button" class="btn primary" data-finalize>Finalize stocktake</button></div></form>`);body.querySelector('[data-close]').onclick=()=>body.closest('.modal').remove();const form=body.querySelector('#stocktakeForm');const rows=d.lines||[];const collect=()=>rows.map(l=>({variantId:l.variant_id,countedQty:form.querySelector(`[name="count_${l.variant_id}"]`)?.value,reason:form.querySelector(`[name="reason_${l.variant_id}"]`)?.value||''}));form.onsubmit=async e=>{e.preventDefault();try{await api('/inventory/stocktakes/'+id+'/count',{method:'PATCH',body:JSON.stringify({lines:collect()})});body.closest('.modal').remove();state.message='Stocktake counts saved';await load('Stocktakes')}catch(err){body.querySelector('#formMsg').innerHTML=`<div class="error">${esc(err.message)}</div>`}};body.querySelector('[data-finalize]').onclick=async()=>{try{await api('/inventory/stocktakes/'+id+'/count',{method:'PATCH',body:JSON.stringify({lines:collect()})});await api('/inventory/stocktakes/'+id+'/finalize',{method:'POST'});body.closest('.modal').remove();state.message='Stocktake finalized';await load('Stocktakes')}catch(err){body.querySelector('#formMsg').innerHTML=`<div class="error">${esc(err.message)}</div>`}}}

async function startStocktake(){const locs=await ensureData('locations');if(!locs.length)throw Error('Create an inventory location first.');await formModal('Start stocktake',[select('Location','locationId',locs[0].id,locs.map(x=>[x.id,x.name])),area('Notes','notes')],x=>api('/inventory/stocktakes',{method:'POST',body:JSON.stringify(x)}),'Start')}
