async function manageTags(id){const tags=await api('/catalog/tags');const product=await api('/catalog/products/'+id);const current=(product.tags||[]).map(x=>x.id);const body=modal('Manage product tags',`<form id="tagForm"><div class="checkgrid">${tags.length?tags.map(t=>`<label class="check"><input type="checkbox" name="tag" value="${esc(t.id)}" ${current.includes(t.id)?'checked':''}>${esc(t.name)}</label>`).join(''):'<div class="empty">No tags have been created.</div>'}</div><div id="formMsg"></div><div class="toolbar" style="justify-content:flex-end"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary">Save</button></div></form>`);body.querySelector('[data-close]').onclick=()=>body.closest('.modal').remove();body.querySelector('#tagForm').onsubmit=async e=>{e.preventDefault();try{const ids=[...e.target.querySelectorAll('input[name="tag"]:checked')].map(x=>x.value);await api('/catalog/products/'+id+'/tags',{method:'POST',body:JSON.stringify({tagIds:ids})});body.closest('.modal').remove();state.message='Product tags updated';return productModal(id)}catch(err){body.querySelector('#formMsg').innerHTML=`<div class="error">${esc(err.message)}</div>`}}}
async function productModal(id){const d=await api('/catalog/products/'+id);const body=modal('Product details',productDetail(d));body.querySelectorAll('[data-action]').forEach(x=>x.onclick=()=>handleAction(x.dataset.action,x));return body}
async function editRole(id){const role=(state.data||[]).find(x=>x.id===id);const perms=await api('/permissions');const body=modal('Edit role',`<form id="roleForm"><div class="formgrid">${field('Name','name',role.name)}${area('Description','description',role.description)}<div class="field span2"><label>Permissions</label><div class="checkgrid">${perms.map(p=>`<label class="check"><input type="checkbox" name="perm" value="${esc(p.id)}" ${(role.permissions||[]).includes(p.id)?'checked':''}>${esc(p.id)}</label>`).join('')}</div></div></div><div id="formMsg"></div><div class="toolbar" style="justify-content:flex-end"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary">Save</button></div></form>`);body.querySelector('[data-close]').onclick=()=>body.closest('.modal').remove();body.querySelector('#roleForm').onsubmit=async e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target).entries());const permissions=[...e.target.querySelectorAll('input[name="perm"]:checked')].map(x=>x.value);await api('/roles/'+id,{method:'PATCH',body:JSON.stringify({...f,permissions})});body.closest('.modal').remove();state.message='Role updated';load('Roles')}catch(err){body.querySelector('#formMsg').innerHTML=`<div class="error">${esc(err.message)}</div>`}}}
